import 'package:flutter/material.dart';

class ToggleableCard extends StatefulWidget {
  const ToggleableCard({Key? key}) : super(key: key);

  @override
  State<ToggleableCard> createState() => _ToggleableCardState();
}

class _ToggleableCardState extends State<ToggleableCard> {
// 1. This is the local state for this widget.
  bool _isSelected = false;

  void _toggleSelection() {
// 3. Update the state and call setState to trigger a rebuild.    setState(() {
      _isSelected = !_isSelected;
    });
  }

  @override
  Widget build(BuildContext context) {
    // 5. The build method uses the current state to render the UI.
    return GestureDetector(
      // 2. An interaction calls our state-changing method.
      onTap: _toggleSelection,
      child: Card(
        color: _isSelected ? Colors.blue[100] : Colors.white,
        child: Container(
          width: 200,
          height: 100,
          child: Center(
            child: Text(_isSelected ? 'Selected!' : 'Tap Me'
              style: TextStyle(fontSize: 24, fontWeight: FontWeight.bold),
),
          ),
        ),
      ),
    );
  }
}

