import 'package:flutter/material.dart';

// --- The Parent Widget ---
class SelectionPage extends StatefulWidget {	
const SelectionPage({Key? key}) : super(key: key);	
  @override	
  State<SelectionPage> createState() => _SelectionPageState();
}

class _SelectionPageState extends State<SelectionPage> {
  // 1. The state now lives in the parent.
  bool _isCardSelected = false;

  // 4. This method updates the parent's state.
  void _handleCardSelection(bool isSelected) {
    setState(() {
      _isCardSelected = isSelected;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Center(
        child: Column(
          children: [
            // 2 & 3. Parent passes down the state value and the callback.
            StatelessToggleableCard(
              isSelected: _isCardSelected,
              onChanged: _handleCardSelection,
            ),
            // This button's state depends on the card's state.            ElevatedButton(
              // Enabled only if the card is selected.              onPressed: _isCardSelected ? () {} : null,
              child: Text('Submit'),
            ),
          ],
        ),
      ),
    );
  }
}

class StatelessToggleableCard extends StatelessWidget {
  final bool isSelected;
  final ValueChanged<bool> onChanged;

  const StatelessToggleableCard({
    required this.isSelected,
    required this.onChanged,
  });

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: () => onChanged(!isSelected),
      child: Card(
        color: isSelected ? Colors.blue[100] : Colors.white,
        child: Container(
          width: 200,
          height: 100,
          child: Center(child: Text(isSelected ? 'Selected!' : 'Tap Me')),
        ),
      ),
    );
  }
}
